mapper.select:
select t.id as taskId, t.project_id, t.task_name, t.description, t.user_id, su.nick_name, t.project_stage_id, ps.stage_name, t.task_priority, t.status, t.execute_status, t.task_process, t.task_pid, t.begin_time, t.end_time, t.close_time, t.created_time from pmhub_project_task t left join sys_user su on su.user_id = t.user_id left join pmhub_project_stage ps on ps.id = t.project_stage_id where t.deleted = 0 and t.project_id = #{data.projectId}
and t.task_name like concat('%',#{data.taskName},'%')
and t.status = #{data.status}
order by t.created_time desc

select pt.task_name, p.project_name, ps.stage_name, su.nick_name as executor, pt.status, pt.execute_status, pt.task_priority, pt.created_by, pt.created_time from pmhub_project_task pt left join pmhub_project p on p.id = pt.project_id left join pmhub_project_stage ps on pt.project_stage_id = ps.id left join sys_user su on su.user_id = pt.user_id where pt.deleted = 0
and pt.id in
#{taskId}
